import json
from collections import Counter

LEVELS = ("INFO", "WARN", "ERROR")

def parse(path="app.log"):
    counts = Counter()
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            level = line.split()[0]
            if level in LEVELS:
                counts[level] += 1
    return {level: counts.get(level, 0) for level in LEVELS}

def main():
    report = parse()
    with open("report.json", "w") as f:
        json.dump(report, f)
    print(report)

if __name__ == "__main__":
    main()

